"""Variant definitions and benchmark shape inventory for SM90 FP8 block GEMM.

Runtime dispatch owns the performance heuristics. This module owns the stable
variant identity and representative shape inventory used by benchmarks.
"""

from dataclasses import dataclass


SM90_FP8_BLOCK_GEMM_FAMILY = "fp8_block_gemm"


@dataclass(frozen=True)
class Sm90Fp8BlockGemmShape:
    name: str
    m: int
    n: int
    k: int
    source: str

    @property
    def padded_k(self) -> int:
        return _round_up(self.k, 128)


@dataclass(frozen=True)
class Sm90Fp8BlockGemmVariant:
    static_m: int
    static_n: int
    static_k: int
    num_sms: int
    scale_a_layout: str
    block_m: int
    block_n: int
    block_k: int
    cluster_m: int
    cluster_n: int
    stages: int
    num_tma_threads: int
    num_math_threads: int
    representative_m: int
    use_pdl: bool = False

    @property
    def cluster_size(self) -> int:
        return self.cluster_m * self.cluster_n

    @property
    def threads(self) -> int:
        return self.num_tma_threads + self.num_math_threads

    @property
    def variant_key(self) -> str:
        return sm90_fp8_block_gemm_variant_key(self)


def _round_up(value: int, multiple: int) -> int:
    return ((value + multiple - 1) // multiple) * multiple


def _compile_m_tag(static_m: int) -> str:
    if static_m == 0:
        return "mdyn"
    if static_m == -1:
        return "msw"
    if static_m == -2:
        return "mpow2"
    if static_m == -3:
        return "mone"
    if static_m > 0:
        return f"m{static_m}"
    raise ValueError(f"unsupported static_m mode {static_m}")


def sm90_fp8_block_gemm_variant_key(variant: Sm90Fp8BlockGemmVariant) -> str:
    return (
        "sm90_1d2d_"
        f"{variant.scale_a_layout}_"
        f"{_compile_m_tag(variant.static_m)}_"
        f"n{variant.static_n}_k{variant.static_k}_"
        f"sms{variant.num_sms}_"
        f"bm{variant.block_m}_bn{variant.block_n}_bk{variant.block_k}_"
        f"c{variant.cluster_m}x{variant.cluster_n}_"
        f"st{variant.stages}_"
        f"tma{variant.num_tma_threads}_math{variant.num_math_threads}"
        f"{'_pdl' if variant.use_pdl else ''}"
    )


def make_sm90_fp8_block_gemm_variant(
    *,
    m: int,
    n: int,
    k: int,
    num_sms: int,
    scale_a_mn_major: bool,
    compile_m: int,
    config,
    force_dynamic_m: bool = False,
    use_pdl: bool = False,
) -> Sm90Fp8BlockGemmVariant:
    static_m = 0 if force_dynamic_m and compile_m > 0 else int(compile_m)
    return Sm90Fp8BlockGemmVariant(
        static_m=static_m,
        static_n=int(n),
        static_k=int(k),
        num_sms=int(num_sms),
        scale_a_layout="mn" if scale_a_mn_major else "row",
        block_m=int(config.block_m),
        block_n=int(config.block_n),
        block_k=int(config.block_k),
        cluster_m=int(config.cluster_m),
        cluster_n=int(config.cluster_n),
        stages=int(config.stages),
        num_tma_threads=int(config.num_tma_threads),
        num_math_threads=int(config.num_math_threads),
        representative_m=int(m),
        use_pdl=bool(use_pdl),
    )


def sm90_fp8_block_gemm_variant_metadata(
    variant: Sm90Fp8BlockGemmVariant,
    *,
    source_shapes: tuple[str, ...] = (),
) -> dict:
    return {
        "dtype": "fp8_e4m3_to_bfloat16",
        "static_m": variant.static_m,
        "static_n": variant.static_n,
        "static_k": variant.static_k,
        "num_sms": variant.num_sms,
        "scale_a_layout": variant.scale_a_layout,
        "block_m": variant.block_m,
        "block_n": variant.block_n,
        "block_k": variant.block_k,
        "cluster_m": variant.cluster_m,
        "cluster_n": variant.cluster_n,
        "stages": variant.stages,
        "num_tma_threads": variant.num_tma_threads,
        "num_math_threads": variant.num_math_threads,
        "representative_m": variant.representative_m,
        "use_pdl": variant.use_pdl,
        "source_shapes": list(source_shapes),
    }


def sm90_fp8_block_gemm_launch_metadata(variant: Sm90Fp8BlockGemmVariant) -> dict:
    launch = {
        "block": [variant.threads, 1, 1],
        "dynamic_smem_bytes": 0,
    }
    if variant.cluster_size > 1:
        launch["cluster"] = [variant.cluster_size, 1, 1]
    return launch


def iter_sm90_fp8_block_gemm_benchmark_shapes() -> tuple[Sm90Fp8BlockGemmShape, ...]:
    return (
        *_qwen36_shapes(),
        *_moondream_siglip_shapes(),
        *_moondream3_text_shapes(),
    )


def iter_sm90_fp8_block_gemm_benchmark_scale_a_layouts(k: int) -> tuple[bool, ...]:
    layouts = (True,)
    if (int(k) // 128) % 4 == 0:
        layouts = (True, False)
    return layouts


def _qwen36_shapes() -> tuple[Sm90Fp8BlockGemmShape, ...]:
    token_m = (64, 128, 256, 512)
    families = (
        ("qwen36.attn.qkv_fused", 9216, 2048),
        ("qwen36.gdn.in_proj_fused", 13312, 2048),
        ("qwen36.gdn.in_proj_qkvz_fused", 12288, 2048),
        ("qwen36.attn_or_gdn.q_or_qkv", 8192, 2048),
        ("qwen36.attn.k_or_v", 512, 2048),
        ("qwen36.gdn.in_proj_z", 4096, 2048),
        ("qwen36.gdn.in_proj_b_or_a", 512, 2048),
        ("qwen36.attn_or_gdn.out_proj", 2048, 4096),
        ("qwen36.shared_expert.gate_up_fused", 1024, 2048),
        ("qwen36.shared_expert.gate_or_up", 512, 2048),
        ("qwen36.shared_expert.down", 2048, 512),
    )
    return tuple(
        Sm90Fp8BlockGemmShape(
            f"{name}.m{m}",
            m,
            n,
            k,
            "Qwen3.6 FP8 dense/shared-expert",
        )
        for name, n, k in families
        for m in token_m
    )


def _moondream_siglip_shapes() -> tuple[Sm90Fp8BlockGemmShape, ...]:
    shapes: list[Sm90Fp8BlockGemmShape] = []
    for crops in range(1, 14):
        m = crops * 729
        shapes.extend(
            (
                Sm90Fp8BlockGemmShape(
                    f"md.siglip.patch_emb.crops{crops}",
                    m,
                    1152,
                    588,
                    "Moondream SigLIP encoder",
                ),
                Sm90Fp8BlockGemmShape(
                    f"md.siglip.attn_qkv.crops{crops}",
                    m,
                    3456,
                    1152,
                    "Moondream SigLIP encoder",
                ),
                Sm90Fp8BlockGemmShape(
                    f"md.siglip.attn_proj.crops{crops}",
                    m,
                    1152,
                    1152,
                    "Moondream SigLIP encoder",
                ),
                Sm90Fp8BlockGemmShape(
                    f"md.siglip.mlp_fc1.crops{crops}",
                    m,
                    4304,
                    1152,
                    "Moondream SigLIP encoder",
                ),
                Sm90Fp8BlockGemmShape(
                    f"md.siglip.mlp_fc2.crops{crops}",
                    m,
                    1152,
                    4304,
                    "Moondream SigLIP encoder",
                ),
            )
        )
    shapes.extend(
        (
            Sm90Fp8BlockGemmShape(
                "md.siglip.proj_mlp_fc1",
                729,
                8192,
                2304,
                "Moondream SigLIP projection",
            ),
            Sm90Fp8BlockGemmShape(
                "md.siglip.proj_mlp_fc2",
                729,
                2048,
                8192,
                "Moondream SigLIP projection",
            ),
        )
    )
    return tuple(shapes)


def _moondream3_text_shapes() -> tuple[Sm90Fp8BlockGemmShape, ...]:
    token_m = (64, 128, 256, 512, 730, 1024)
    token_families = (
        ("md3.text.attn_qkv", 6144, 2048),
        ("md3.text.attn_proj", 2048, 2048),
        ("md3.text.tau_wqwv", 64, 6144),
        ("md3.text.dense_mlp_fc1", 8192, 2048),
        ("md3.text.dense_mlp_fc2", 2048, 8192),
        ("md3.text.moe_router", 64, 2048),
    )
    shapes = [
        Sm90Fp8BlockGemmShape(
            f"{name}.m{m}",
            m,
            n,
            k,
            "Moondream 3 text dense",
        )
        for name, n, k in token_families
        for m in token_m
    ]
    shapes.extend(
        Sm90Fp8BlockGemmShape(
            f"md3.text.lm_head.m{m}",
            m,
            51200,
            2048,
            "Moondream 3 text lm_head",
        )
        for m in (64, 128, 256, 512)
    )
    return tuple(shapes)
